def compute(vars):
    useful_life = vars["v1"]
    if useful_life == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    rate = 100 / useful_life
    return {
        "value": rate,
        "trace": {
            "useful_life_years": useful_life,
            "annual_amortization_rate_percentage": rate,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        },
    }
